package com.hbm.client.oilextraction;
import com.hbm.machine.oilextraction.*;import java.util.*;import me.shedaniel.math.*;import me.shedaniel.rei.api.client.gui.Renderer;import me.shedaniel.rei.api.client.gui.widgets.*;import me.shedaniel.rei.api.client.plugins.REIClientPlugin;import me.shedaniel.rei.api.client.registry.category.CategoryRegistry;import me.shedaniel.rei.api.client.registry.display.*;import me.shedaniel.rei.api.common.category.CategoryIdentifier;import me.shedaniel.rei.api.common.display.basic.BasicDisplay;import me.shedaniel.rei.api.common.entry.*;import me.shedaniel.rei.api.common.util.EntryStacks;import me.shedaniel.rei.forge.REIPluginClient;import net.minecraft.network.chat.Component;
@REIPluginClient public final class OilExtractionReiPlugin implements REIClientPlugin {
 static final CategoryIdentifier<Display> TYPE=CategoryIdentifier.of("hbm","oil_extraction");@Override public void registerCategories(CategoryRegistry e){e.add(new Category());for(var item:OilExtractionContent.ITEM.values())e.addWorkstations(TYPE,EntryStacks.of(item.get()));}@Override public void registerDisplays(DisplayRegistry e){for(var recipe:OilExtractionViews.recipes())e.add(new Display(recipe));}
 private static final class Display extends BasicDisplay{final OilExtractionViews.Extraction recipe;Display(OilExtractionViews.Extraction r){super(List.of(EntryIngredient.of(EntryStacks.of(r.deposit())),EntryIngredient.of(EntryStacks.of(OilExtractionContent.ITEM.get(r.kind()).get()))),List.of(EntryIngredient.of(EntryStacks.of(r.oil())),EntryIngredient.of(EntryStacks.of(r.gas())),EntryIngredient.of(EntryStacks.of(r.depleted()))));recipe=r;}@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}}
 private static final class Category implements DisplayCategory<Display>{@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}@Override public Component getTitle(){return Component.translatable("recipe.hbm.oil_extraction");}@Override public Renderer getIcon(){return EntryStacks.of(OilExtractionContent.ITEM.get(OilDrillKind.WELL).get());}@Override public int getDisplayWidth(Display d){return 166;}@Override public int getDisplayHeight(){return 106;}@Override public List<Widget> setupDisplay(Display d,Rectangle bounds){var result=new ArrayList<Widget>();result.add(Widgets.createRecipeBase(bounds));for(int i=0;i<2;i++)result.add(Widgets.createSlot(new Point(bounds.x+8+i*30,bounds.y+24)).entries(d.getInputEntries().get(i)));int[][] xy={{92,15},{120,15},{92,43}};for(int i=0;i<3;i++)result.add(Widgets.createSlot(new Point(bounds.x+xy[i][0],bounds.y+xy[i][1])).entries(d.getOutputEntries().get(i)).markOutput());Component[] lines={Component.translatable("gui.hbm.oil_drill.interval",d.recipe.config().delay()),Component.translatable("gui.hbm.oil_drill.consumption",d.recipe.config().consumption()),OilExtractionViews.gas(d.recipe),OilExtractionViews.depletion(d.recipe)};for(int i=0;i<lines.length;i++)result.add(Widgets.createLabel(new Point(bounds.x+83,bounds.y+66+i*10),lines[i]).color(0x404040).noShadow());return result;}}
}
